import heapq


def eatenApples(apples, days):
    n = len(apples)
    h = []
    eaten = 0
    i = 0
    while i < n or h:
        if i < n and apples[i] > 0:
            heapq.heappush(h, [i + days[i], apples[i]])
        while h and h[0][0] <= i:
            heapq.heappop(h)
        if h:
            h[0][1] -= 1
            eaten += 1
            if h[0][1] == 0:
                heapq.heappop(h)
        i += 1
    return eaten
